<script setup lang="ts">
import { ref, watch, onUnmounted } from 'vue'
import { app, legacyUrl, prepareLegacy, selectProject } from '../app'
import { get } from '../api/client'
type Item={key:string;title:string;project:string;status:string;assignee:string;reviewer:string;next_actor:string|null;stage_label:string;attention_reason:string;action_label:string;action_href:string;running:boolean;handoff:null|{status:string;block_reason?:string};meeting_action?:{meeting_id:string;meeting_title:string}}
type Queue={items:Item[];total:number;offset:number;has_more:boolean;counts:Record<string,number>;attention_count:number;incoming_count:number}
const scope=ref('*'),view=ref('team'),stage=ref('all'),query=ref(''),offset=ref(0),loading=ref(false),error=ref(''),data=ref<Queue|null>(null)
const views=[['team','团队全部'],['attention','需要我处理'],['mine','我负责'],['incoming','待我接收'],['review','待我复核'],['unassigned','待分配']]
const stages=[['all','全部阶段'],['requirement','需求'],['development','研发'],['testing','测试'],['delivery','交付'],['operations','运维'],['unrecorded','未登记阶段']]
let generation=0
async function load(){const n=++generation;loading.value=true;error.value='';try{const result=await get<Queue>('/api/workspace?'+new URLSearchParams({project:scope.value,view:view.value,stage:stage.value,q:query.value,offset:String(offset.value),limit:'30'}));if(n===generation)data.value=result}catch(e){if(n===generation)error.value=String(e)}finally{if(n===generation)loading.value=false}}
function search(){if(scope.value!=='*')selectProject(scope.value);offset.value=0;load()}
watch([scope,view,stage],search,{immediate:true})
onUnmounted(()=>generation++)
</script>
<template><header class="workspace-heading"><div><h1>任务总览</h1><span v-if="data" class="muted">{{data.counts.team}} 项进行中 · {{data.counts.unassigned}} 项待分配 · {{data.counts.review}} 项待我复核</span></div><div class="actions"><router-link class="btn" to="/projects">项目与仓库</router-link><router-link class="btn" to="/features">全部功能</router-link><router-link v-if="app.project" class="btn btn-primary" :to="`/p/${encodeURIComponent(app.project)}/work?compose=1`">新需求</router-link></div></header>
<section v-if="!app.projects.length" class="start-panel">
  <div><h2>接入项目，开始协作</h2><p>导入 Git 仓库、接入本地代码，或创建新项目。</p><router-link class="btn btn-primary" to="/projects">接入项目 →</router-link></div>
  <div class="start-links"><router-link to="/settings">配置 AI 执行器 <span>→</span></router-link><router-link to="/features">浏览全部功能 <span>→</span></router-link></div>
</section>
<template v-else>
<nav class="queue-tabs" aria-label="任务范围"><button v-for="[key,label] in views" :key="key" :class="{active:view===key}" @click="view=key!">{{label}}</button></nav>
<form class="filters" @submit.prevent="search"><label class="field">项目<select v-model="scope"><option value="*">全部项目</option><option v-for="p in app.projects" :key="p.key" :value="p.key">{{p.name||p.key}}</option></select></label><label class="field">阶段<select v-model="stage"><option v-for="[key,label] in stages" :key="key" :value="key">{{label}}</option></select></label><label class="field search">查找任务<input v-model="query" placeholder="名称、编号、正文或责任人" /></label><button class="btn" :disabled="loading">{{loading?'读取中…':'查询'}}</button></form>
<p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!loading&&!error&&!data?.items.length" class="empty">当前范围没有待处理任务。<router-link to="/features">查看已交付记录与全部功能</router-link></p>
<div class="queue"><article v-for="item in data?.items" :key="item.key" class="queue-row"><div class="task-main"><div class="muted">{{item.key}} · {{item.stage_label}}<span v-if="item.running"> · 正在执行</span></div><h2><a :href="legacyUrl('/t/'+encodeURIComponent(item.key))" @click="prepareLegacy(item.project)">{{item.title}}</a></h2><p>{{item.handoff?.block_reason || item.attention_reason}}</p><a v-if="item.meeting_action" :href="legacyUrl('/meetings/'+encodeURIComponent(item.meeting_action.meeting_id)+'/'+encodeURIComponent(item.project))" @click="prepareLegacy(item.project)">会议：{{item.meeting_action.meeting_title}}</a></div><div class="owner"><span class="muted">下一责任人</span><strong>{{item.next_actor || '待分配'}}</strong><span class="muted">负责人 {{item.assignee||'未指定'}}<br/>复核人 {{item.reviewer||'未指定'}}</span></div><div class="actions"><a class="btn btn-primary" :href="legacyUrl(item.action_href)" @click="prepareLegacy(item.project)">{{item.action_label}}</a><router-link class="btn" :to="`/p/${encodeURIComponent(item.project)}/work?ticket=${encodeURIComponent(item.key)}`">开发记录</router-link></div></article></div>
<footer v-if="data" class="pagination"><span>{{data.total ? offset+1 : 0}}—{{offset+(data.items.length)}} / {{data.total}}</span><button class="btn" :disabled="loading||offset===0" @click="offset=Math.max(0,offset-30);load()">上一页</button><button class="btn" :disabled="loading||!data.has_more" @click="offset+=30;load()">下一页</button></footer>
</template>
</template>
<style scoped>.start-panel{display:grid;grid-template-columns:2fr 1fr;gap:40px;background:var(--panel);border:1px solid var(--line);border-radius:12px;margin-top:32px;padding:40px}.start-panel h2{font-size:26px;margin:0 0 12px}.start-panel p{color:var(--sub);margin-bottom:26px}.start-links{display:flex;flex-direction:column;justify-content:center;gap:16px}.start-links a{display:flex;justify-content:space-between;text-decoration:none;border-bottom:1px solid var(--line);padding:12px 0}@media(max-width:760px){.start-panel{grid-template-columns:1fr;padding:24px;gap:24px}}.workspace-heading{display:flex;justify-content:space-between;gap:20px;align-items:center}.workspace-heading h1{margin-bottom:6px}.actions{display:flex;gap:8px;flex-wrap:wrap}.queue-tabs{display:flex;gap:18px;margin:28px 0 20px;border-bottom:1px solid var(--line);overflow-x:auto}.queue-tabs button{background:none;border:0;border-bottom:2px solid transparent;padding:10px 0;white-space:nowrap;color:var(--sub);cursor:pointer}.queue-tabs .active{color:var(--accent);border-color:var(--accent)}.filters{display:flex;align-items:end;gap:12px;flex-wrap:wrap;margin-bottom:24px}.filters .field{margin:0}.search{flex:1;min-width:180px}.queue-row{display:grid;grid-template-columns:minmax(0,1fr) 150px auto;gap:24px;align-items:center;border-top:1px solid var(--line);padding:22px 0}.queue-row h2{margin:5px 0}.queue-row h2 a{color:var(--fg);text-decoration:none}.queue-row p{margin:6px 0;color:var(--sub);overflow-wrap:anywhere}.owner{display:flex;flex-direction:column;gap:5px}.pagination{display:flex;justify-content:flex-end;align-items:center;gap:12px;margin-top:24px;font-variant-numeric:tabular-nums}@media(max-width:1000px){.queue-row{grid-template-columns:minmax(0,1fr) 140px}.queue-row .actions{grid-column:1/-1}}@media(max-width:760px){.workspace-heading{align-items:start;flex-direction:column}.queue-row{grid-template-columns:1fr}.queue-row .actions{grid-column:auto}.owner{flex-direction:row;flex-wrap:wrap;gap:10px}.filters .field{flex:1;min-width:140px}}</style>
